00040 // Template definitions for SurfaceBuilder<T> amd SurfaceView<T>
00041 
00042 template <typename T> SurfaceBuilder<T>::SurfaceBuilder() : surface_(new Surface("", 0, 0, 0, 0, 0, 0)) {}
00043 
00044 // From a view into another surface
00045 template <typename T>
00046 SurfaceBuilder<T> &SurfaceBuilder<T>::contents(const SurfaceView<T> &view, unsigned x, unsigned y, unsigned width,
00047                                                unsigned height) {
00048 
00049     // Pixels must be same size (but can be reinterpreted as different similar sized types)
00050     assert(view.surface_.bpp_ == sizeof(T));
00051 
00052     *surface_ = view.surface_;
00053 
00054     assert(x <= surface_->width());
00055     assert(x + width <= surface_->width());
00056     assert(y <= surface_->height());
00057     assert(y + height <= surface_->height());
00058 
00059     surface_->offset_ += (y * surface_->stride_) + x * surface_->bpp_;
00060     surface_->width_ = width;
00061     surface_->height_ = height;
00062 
00063     return *this;
00064 }
00065 
00066 template <typename T>
00067 SurfaceBuilder<T> &SurfaceBuilder<T>::contents(const T *data, unsigned width, unsigned height, unsigned data_stride) {
00068     surface_->bpp_ = sizeof(T);
00069     surface_->stride_ = width * sizeof(T);
00070     surface_->buffer_ = std::shared_ptr<Buffer>(CreateBufferAligned(height * surface_->stride_));
00071     surface_->offset_ = 0;
00072     surface_->width_ = width;
00073     surface_->height_ = height;
00074 
00075     uint8_t *mapped_data = nullptr;
00076     unsigned mapped_size = 0;
00077 
00078     surface_->buffer_->map_write(0, height * surface_->stride_, mapped_data, mapped_size);
00079 
00080     if (data_stride == 0 || data_stride == surface_->stride_) {
00081         // Contiguous - use a single memcpy
00082         CHECK(mapped_size >= height * surface_->stride_);
00083         memcpy(mapped_data, data, height * surface_->stride_);
00084     } else {
00085         // Strided - copy line by line
00086         const uint8_t *src = (const uint8_t *)data;
00087         uint8_t *dest = mapped_data;
00088 
00089         for (unsigned y = 0; y < height; ++y) {
00090             memcpy(dest, src, width * surface_->bpp_);
00091             dest += surface_->stride_;
00092             src += data_stride;
00093         }
00094     }
00095 
00096     surface_->buffer_->unmap();
00097     return *this;
00098 }
00099 
00100 template <typename T> SurfaceBuilder<T> &SurfaceBuilder<T>::reserve(unsigned width, unsigned height, unsigned stride) {
00101     surface_->bpp_ = sizeof(T);
00102     surface_->stride_ = stride ? stride : (width * sizeof(T));
00103     surface_->buffer_ = std::shared_ptr<Buffer>(CreateBufferAligned(height * surface_->stride_));
00104     surface_->offset_ = 0;
00105     surface_->width_ = width;
00106     surface_->height_ = height;
00107 
00108     surface_->buffer_->map_write(surface_->offset_, height * surface_->stride_, mapped_data_, mapped_size_);
00109     mapped_stride_ = surface_->stride_;
00110     return *this;
00111 }
00112 
00113 template <typename T>
00114 SurfaceBuilder<T> &SurfaceBuilder<T>::reserve_bpp(unsigned width, unsigned height, unsigned bpp, unsigned stride) {
00115     surface_->bpp_ = bpp;
00116     surface_->stride_ = stride ? stride : (width * bpp);
00117     surface_->buffer_ = std::shared_ptr<Buffer>(CreateBufferAligned(height * surface_->stride_));
00118     surface_->offset_ = 0;
00119     surface_->width_ = width;
00120     surface_->height_ = height;
00121 
00122     surface_->buffer_->map_write(surface_->offset_, height * surface_->stride_, mapped_data_, mapped_size_);
00123     mapped_stride_ = surface_->stride_;
00124     return *this;
00125 }
00126 
00127 template <typename T> T *SurfaceBuilder<T>::data() const {
00128     assert(mapped_data_ != nullptr);
00129     return reinterpret_cast<T *>(mapped_data_);
00130 }
00131 
00132 template <typename T> T *SurfaceBuilder<T>::data(unsigned x, unsigned y) const {
00133     assert(mapped_data_ != nullptr);
00134     assert(x < width() && y < height());
00135     return reinterpret_cast<T *>(mapped_data_ + y * mapped_stride_) + x;
00136 }
00137 
00138 template <typename T> void SurfaceBuilder<T>::write(unsigned x, unsigned y, T t) { *data(x, y) = t; }
00139 
00140 template <typename T> unsigned SurfaceBuilder<T>::width() const { return surface_->width_; }
00141 
00142 template <typename T> unsigned SurfaceBuilder<T>::height() const { return surface_->height_; }
00143 
00144 template <typename T> unsigned SurfaceBuilder<T>::stride() const {
00145     assert(mapped_data_ != nullptr);
00146 
00147     return mapped_stride_;
00148 }
00149 
00150 template <typename T> SurfaceBuilder<T> &SurfaceBuilder<T>::name(const std::string &name) {
00151     surface_->name_ = name;
00152     return *this;
00153 }
00154 
00155 template <typename T> Surface SurfaceBuilder<T>::finish() {
00156     if (mapped_data_) {
00157         surface_->buffer_->unmap();
00158         mapped_data_ = nullptr;
00159         mapped_stride_ = 0;
00160     }
00161     return *surface_;
00162 }
00163 
00164 // Generate new contents using a function of (x,y)
00165 //
00166 template <typename T>
00167 SurfaceBuilder<T> &SurfaceBuilder<T>::generate(unsigned width, unsigned height, std::function<T(unsigned x, unsigned y)> fn) {
00168     reserve(width, height);
00169     for (unsigned y = 0; y < height; ++y)
00170         for (unsigned x = 0; x < width; ++x)
00171             write(x, y, fn(x, y));
00172 
00173     return *this;
00174 }
00175 
00176 template <typename T>
00177 template <typename C>
00178 SurfaceBuilder<T> &SurfaceBuilder<T>::generate(unsigned width, unsigned height, T (*fn)(unsigned x, unsigned y, const C &c),
00179                                                const C &c) {
00180     reserve(width, height);
00181     for (unsigned y = 0; y < height; ++y)
00182         for (unsigned x = 0; x < width; ++x)
00183             write(x, y, fn(x, y, c));
00184 
00185     return *this;
00186 }
00187 
00188 template <typename T>
00189 template <typename A1>
00190 SurfaceBuilder<T> &SurfaceBuilder<T>::generate(unsigned width, unsigned height, T (*fn)(unsigned x, unsigned y, A1 a1), A1 a1) {
00191     reserve(width, height);
00192     for (unsigned y = 0; y < height; ++y)
00193         for (unsigned x = 0; x < width; ++x)
