00200 template <typename A1, typename A2>
00201 SurfaceBuilder<T> &SurfaceBuilder<T>::generate(unsigned width, unsigned height, T (*fn)(unsigned x, unsigned y, A1 a1, A2 a2),
00202                                                A1 a1, A2 a2) {
