00211 template <typename T>
00212 template <typename A1, typename A2, typename A3>
00213 SurfaceBuilder<T> &SurfaceBuilder<T>::generate(unsigned width, unsigned height,
00214                                                T (*fn)(unsigned x, unsigned y, A1 a1, A2 a2, A3 a3), A1 a1, A2 a2, A3 a3) {
00215     reserve(width, height);
00216     for (unsigned y = 0; y < height; ++y)
00217         for (unsigned x = 0; x < width; ++x)
00218             write(x, y, fn(x, y, a1, a2, a3));
