00223 template <typename T> SurfaceBuilder<T> &SurfaceBuilder<T>::fill(T value, unsigned width, unsigned height) {
00224     reserve(width, height);
00225     for (unsigned y = 0; y < height; ++y)
00226         for (unsigned x = 0; x < width; ++x)
00227             write(x, y, value);
00228 
00229     return *this;
00230 }
00231 
00232 template <typename T> template <typename F> SurfaceBuilder<T> &SurfaceBuilder<T>::xgenerate(unsigned width, unsigned height, F fn) {
00233     reserve(width, height);
00234     for (unsigned y = 0; y < height; ++y)
00235         for (unsigned x = 0; x < width; ++x)
00236             write(x, y, fn(x, y));
00237 
00238     return *this;
