00242 //
00243 //
00244 template <typename T, unsigned S> SurfaceView<T, S>::SurfaceView(const Surface &surface) : surface_(surface) {
00245     surface.buffer_->map_read(surface.offset_, surface.height_ * surface_.stride_, mapped_data_, mapped_size_);
00246     mapped_stride_ = surface_.stride_;
00247 }
00248 
00249 template <typename T, unsigned S> SurfaceView<T, S>::~SurfaceView() { surface_.buffer_->unmap(); }
00250 
00251 template <typename T, unsigned S> const T *SurfaceView<T, S>::data() const { return reinterpret_cast<const T *>(mapped_data_); }
00252 
00253 template <typename T, unsigned S> const T *SurfaceView<T, S>::data(unsigned x, unsigned y) const {
00254     assert((x >> S) < width() && (y >> S) < height());
00255     return reinterpret_cast<const T *>(mapped_data_ + (y >> S) * mapped_stride_) + (x >> S);
00256 }
00257 
00258 template <typename T, unsigned S> T SurfaceView<T, S>::read(unsigned x, unsigned y) const { return *data(x, y); }
00259 
00260 template <typename T, unsigned S> unsigned SurfaceView<T, S>::width() const { return surface_.width_; }
00261 
00262 template <typename T, unsigned S> unsigned SurfaceView<T, S>::height() const { return surface_.height_; }
00263 
00264 template <typename T, unsigned S> unsigned SurfaceView<T, S>::size() const { return surface_.height_ * surface_.stride_; };
00265 
00266 template <typename T, unsigned S> unsigned SurfaceView<T, S>::row_size() const { return surface_.width_ * surface_.bpp_; };
00267 
00268 template <typename T, unsigned S> bool SurfaceView<T, S>::rows_are_contiguous() const {
00269     return mapped_stride_ == surface_.width_ * surface_.bpp_;
00270 }
00271 
00272 // Surface
00273 //
00274 template <typename T, unsigned S> SurfaceView<T, S> Surface::view_as() const { return SurfaceView<T, S>(*this); }
